  --radius: 8px;
  --shadow-sm: 0 1px 3px rgba(0, 0, 0, 0.12), 0 1px 2px rgba(0, 0, 0, 0.24);
  --shadow-md: 0 3px 6px rgba(0, 0, 0, 0.16), 0 3px 6px rgba(0, 0, 0, 0.23);
  --transition: 150ms ease-in-out;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html, body {
  height: 100%;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  color: var(--color-text);
  background: linear-gradient(135deg, #f5f7fa 0%, #c3cfe2 100%);
  min-height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: var(--spacing-sm);
}

main {
  width: 100%;
}

.container {
  background: var(--color-bg);
  border-radius: var(--radius);
  box-shadow: var(--shadow-md);
  padding: var(--spacing-lg);
  max-width: 500px;
  margin: 0 auto;
}

h1 {
  font-size: 1.75rem;
  font-weight: 600;
  margin-bottom: var(--spacing-md);
  color: var(--color-text);
}

.intro-text {
  color: var(--color-text-secondary);
  margin-bottom: var(--spacing-lg);
  font-size: 0.95rem;
}

form {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-md);
}

.form-field {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-xs);
}

/* Checkbox styling */
input[type="checkbox"] {
  appearance: none;
  -webkit-appearance: none;
  -moz-appearance: none;
  width: 20px;
  height: 20px;
  border: 2px solid var(--color-border);
  border-radius: 4px;
  background-color: var(--color-bg);
  cursor: pointer;
  flex-shrink: 0;
  margin-right: var(--spacing-sm);
  transition: all var(--transition);
  outline: none;
}

input[type="checkbox"]:hover:not(:disabled) {
  border-color: var(--color-primary);
  background-color: #f0f7ff;
}

input[type="checkbox"]:focus {
  outline: 3px solid var(--color-focus);
  outline-offset: 2px;
  border-color: var(--color-primary);
}

input[type="checkbox"]:checked {
  background-color: var(--color-primary);
  border-color: var(--color-primary);
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 16 16' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M3 8l3 3 7-7' stroke='white' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'/%3E%3C/svg%3E");
  background-repeat: no-repeat;
  background-position: center;
  background-size: 12px;
}

input[type="checkbox"]:checked:focus {
  border-color: var(--color-primary);
}

input[type="checkbox"]:disabled {
  background-color: #f5f5f5;
  border-color: var(--color-border);
  cursor: not-allowed;
  opacity: 0.6;
}

input[type="checkbox"][aria-invalid="true"] {
  border-color: var(--color-error);
  border-width: 2px;
}

input[type="checkbox"][aria-invalid="true"]:focus {
  outline-color: #ff6b6b;
}

/* Label styling */
label {
  display: flex;
  align-items: flex-start;
  gap: var(--spacing-sm);
  cursor: pointer;
  font-size: 0.95rem;
  line-height: 1.4;
}

label a {
  color: var(--color-primary);
  text-decoration: underline;
  transition: color var(--transition);
}

label a:hover {
  color: var(--color-primary-dark);
}

label a:focus {
  outline: 2px solid var(--color-focus);
  outline-offset: 2px;
  border-radius: 2px;
}

/* Helper and error text */
.helper-text {
  font-size: 0.85rem;
  color: var(--color-text-secondary);
  margin-left: 28px;
  line-height: 1.4;
}

.error-text {
  font-size: 0.85rem;
  color: var(--color-error);
  background-color: var(--color-error-bg);
  padding: var(--spacing-xs) var(--spacing-sm);
  border-radius: 4px;
  margin-left: 28px;
  border-left: 3px solid var(--color-error);
}

/* Button styling */
.btn-submit {
  background-color: var(--color-primary);
  color: white;
  border: none;
  padding: var(--spacing-sm) var(--spacing-lg);
  font-size: 1rem;
  font-weight: 600;
  border-radius: var(--radius);
  cursor: pointer;
  transition: all var(--transition);
  outline: none;
  margin-top: var(--spacing-sm);
}

.btn-submit:hover {
  background-color: var(--color-primary-dark);
  box-shadow: var(--shadow-sm);
}

.btn-submit:focus {
  outline: 3px solid var(--color-focus);
  outline-offset: 2px;
  box-shadow: var(--shadow-sm);
}

.btn-submit:active {
  transform: translateY(1px);
}

.btn-submit:disabled {
  background-color: #9e9e9e;
  cursor: not-allowed;
  opacity: 0.7;
}

/* Success state */
.form-field.success input[type="checkbox"] {
  border-color: #4caf50;
  background-color: #4caf50;
}

/* Responsive */
@media (max-width: 480px) {
  .container {
    padding: var(--spacing-md);
  }

  h1 {
    font-size: 1.5rem;
  }

  .btn-submit {
    padding: var(--spacing-sm) var(--spacing-md);
    font-size: 0.95rem;
  }
}

/* High contrast / Forced Colors support */
@media (prefers-contrast: more) {
  input[type="checkbox"] {
    border-width: 3px;
  }

  input[type="checkbox"]:focus {
    outline-width: 4px;
  }
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  * {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}
