document.addEventListener('DOMContentLoaded', () => {
  const form = document.getElementById('consent-form');
  const checkbox = document.getElementById('agree-terms');
  const errorElement = document.getElementById('terms-error');

  // Handle form submission
  form.addEventListener('submit', (e) => {
    e.preventDefault();

    if (!checkbox.checked) {
      // Set error state
      checkbox.setAttribute('aria-invalid', 'true');
      errorElement.hidden = false;
      checkbox.focus();
    } else {
      // Clear error state
      checkbox.setAttribute('aria-invalid', 'false');
      errorElement.hidden = true;

      // Show success (optional visual feedback)
      form.querySelector('.form-field').classList.add('success');

      // Simulate success action
      console.log('Consent accepted. Form would submit here.');
      // In a real application, you would submit the form data to a server
      // Example: fetch('/api/consent', { method: 'POST', ... })
    }
  });

  // Clear error on checkbox change
  checkbox.addEventListener('change', () => {
    if (checkbox.checked) {
      checkbox.setAttribute('aria-invalid', 'false');
      errorElement.hidden = true;
    }
  });
});

